def _extract_order_ids(payload):
    ids = set()
    if isinstance(payload, dict):
        # Common shapes: {"result":[...]} or {"orders":[...]} or direct list
        for key in ("result", "orders"):
            if key in payload and isinstance(payload[key], list):
                for o in payload[key]:
