                ids.add(o["id"])
    return list(ids)


def _try_list_open_orders(dc):
    # Try a few likely endpoints, be tolerant to shapes
    tries = [
        ("GET", "/v2/open_orders", None),
        ("GET", "/v2/orders/open", None),
        ("GET", "/v2/orders", {"status": "open"}),
    ]
    last_err = None
    for method, path, params in tries:
